import { useState, useEffect } from 'react';
import axios from 'axios';

const Category = () => {
  const [categories, setCategories] = useState([]);
  const [name, setName] = useState('');
  const [image, setImage] = useState(null);
    const [searchTerm, setSearchTerm] = useState('');

  useEffect(() => {
    fetchCategories();
  }, []);

  const fetchCategories = async () => {
    try {
      const response = await axios.get('http://localhost:5000/api/users/allcategories');
      setCategories(response.data);
    } catch (error) {
      console.error("Error fetching categories:", error);
    }
  };

  const handleAddCategory = async (e) => {
    e.preventDefault();

    const formData = new FormData();
    formData.append("name", name);
    formData.append("image", image);

    try {
      const response = await axios.post('http://localhost:5000/api/users/addcategory', formData, {
        headers: {
          "Content-Type": "multipart/form-data"
        }
      });

      console.log("Category added:", response.data);
      setName('');
      setImage(null);
      fetchCategories();
    } catch (error) {
      console.error("Error adding category:", error);
    }
  };

  return (
    <div
      style={{
        display: "flex",
        padding: "40px",
        fontFamily: "Arial, sans-serif",
        gap: "40px",
        alignItems: "flex-start"
      }}
    >
      {/* Left: Category Cards */}
      <div style={{ flex: 1 }}>
        <h2 style={{ fontSize: "40px", marginBottom: "20px", color: "#333" }}>CATEGORIES</h2>
        <div style={{ display: "flex", flexWrap: "wrap", gap: "20px" }}>
         {catr
  .filter((cat) => cat.name.toLowerCase().includes(searchTerm.toLowerCase()))
  .map((cat) => (
            <div
              key={cat._id}
              style={{
                width: "220px",
                border: "1px solid #ddd",
                borderRadius: "10px",
                overflow: "hidden",
                backgroundColor: "#fff",
                boxShadow: "0 4px 12px rgba(0, 0, 0, 0.08)",
                transition: "transform 0.2s ease",
                cursor: "pointer"
              }}
              onMouseOver={(e) => {
                e.currentTarget.style.transform = "translateY(-5px)";
              }}
              onMouseOut={(e) => {
                e.currentTarget.style.transform = "translateY(0)";
              }}
            >
              <img
                src={`http://localhost:5000/uploads/${cat.image}`}
                alt={cat.name}
                style={{ width: "100%", height: "200px", objectFit: "cover" }}
              />
              <div style={{ padding: "12px", textAlign: "center" }}>
                <h4 style={{ margin: "0", fontSize: "18px", color: "#333" }}>{cat.name}</h4>
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Right: Add Category Form Box */}
      <div
        style={{
          marginTop: "130px",
          width: "320px",
          padding: "20px",
          border: "1px solid #ddd",
          borderRadius: "10px",
          backgroundColor: "#f9f9f9",
          boxShadow: "0 4px 12px rgba(0, 0, 0, 0.08)",
          height: "400px",
          backgroundColor: "lightblue",
        }}
      >
<h2>Search Categories</h2>
         <input
  type="text"
  placeholder="Search.."
  value={searchTerm}
  onChange={(e) => setSearchTerm(e.target.value)}
  style={{
    backgroundColor: 'white',
    borderRadius: '5px',
    padding: '6px 10px',
    width: '300px',
    height: '30px',
    border: '1px white',
    marginBottom: '65px',
  }}
/>
        <h2 style={{ marginBottom: "20px",color:"black" }}> Add New Category</h2>
        <form
          onSubmit={handleAddCategory}
          encType="multipart/form-data"
          style={{
            display: "flex",
            flexDirection: "column",
            gap: "15px"
          }}
        >
          <input
            type="text"
            placeholder="Category Name"
            value={name}
            onChange={(e) => setName(e.target.value)}
            required
            style={{
              padding: "10px",
              borderRadius: "6px",
              border: "1px solid white",
              color: "black",
            }}
          />
          <input
            type="file"
            accept="image/*"
            onChange={(e) => setImage(e.target.files[0])}
            required
            style={{
              padding: "10px",
              borderRadius: "6px",
              border: "1px solid white",
              backgroundColor: "white",
            }}
          />
          <button
            type="submit"
            style={{
              padding: "10px 20px",
              backgroundColor: "black",
              color: "white",
              border: "none",
              borderRadius: "6px",
              cursor: "pointer"
            }}
          >
            Add Category
          </button>
        </form>
      </div>
    </div>
  );
};

export default Category;
